/*
 * Produce a node consisting
 * of an octal number.
 */
NODE *onode(int (*fun)(NODE *))
{
	register char *ap;
	unsigned long num;
	register NODE *np;
	register int type;
	char *aap;

	if ((ap = next()) == NULL)
		errx(1, "Missing octal permission");
	aap = ap;
	if (*ap == '-') {
		ap++;
		type = -1;
	} else
		type = 0;
	num = 0;
	while (*ap>='0' && *ap<='7') {
        num = num*8 + *ap++-'0';
        if (num > 07777) errx(1, "%s: bad octal permission", aap);
    }
	if (*ap != '\0')
		errx(1, "%s: bad octal permission", aap);
	np = inode(fun, num);
	np->n_un.n_val = num;
	np->n_type = type;
	return (np);
}

/*
 * Get a number -- it also may be
 * prefixed by `+' or `-' to
 * represent quantities greater or
 * less.
 */
NODE *nnode(int (*fun)(NODE *))
{
	register char *ap;
	unsigned long num = 0;
	register int type = 0;
	register NODE *np;
	char *aap;

	if ((ap = next()) == NULL)
		errx(1, "Missing number");
	aap = ap;
	if (*ap == '+') {
		type = 1;
		ap++;
	} else if (*ap == '-') {
		type = -1;
		ap++;
	}
    if (*ap < '0' || *ap > '9')
        errx(1, "%s: invalid number", aap);
	while (*ap>='0' && *ap<='9')
		{
        unsigned digit = *ap++ - '0';
        if (num > (4294967295UL - digit) / 10)
            errx(1, "%s: number too large", aap);
        num = num*10 + digit;
    }
	if (*ap && !(fun == xsize && *ap == 'c' && !ap[1]))
        errx(1, "%s: invalid number", aap);
	np = inode(fun, num);
	np->n_type = type;
    np->n_chars = *ap == 'c';
	return (np);
}

/*
 * Get a user name or number.
 */
NODE *getuser(void)
{
	register struct passwd *pwp;
	register char *cp;
	register int uid;

	if ((cp = next()) == NULL)
		errx(1, "Missing username");
	if (*cp>='0' && *cp<='9')
		uid = atoi(cp);
	else {
		if ((pwp = getpwnam(cp)) == NULL)
			errx(1, "%s: bad user name", cp);
		uid = pwp->pw_uid;
	}
	return (lnode(FUN, xuser, uid, NULL));
}

/*
 * Get group
 */
NODE *getgroup(void)
{
	register struct group *grp;
	register char *cp;
	register int gid;

	if ((cp = next()) == NULL)
		errx(1, "Missing group name");
	if (*cp>='0' && *cp<='9')
		gid = atoi(cp);
	else {
		if ((grp = getgrnam(cp)) == NULL)
			errx(1, "%s: bad group name", cp);
		gid = grp->gr_gid;
	}
	return (lnode(FUN, xgroup, gid, NULL));
}

/*
 * Get the time for the file used in
 * the `-newer' primary.
 */
NODE *getnewer(void)
{
	register NODE *np;
	register char *fn;

	if ((fn = next()) == NULL)
		errx(1, "Missing filename for `-newer'");
	if (stat(fn, &sb) < 0)
		errx(1, "%s: nonexistent", fn);
	np = inode(xnewer, 0);
	np->n_un.n_time = sb.st_mtime;
	return (np);
}

/*
 * Build an expression tree node (non-leaf).
 */
NODE *bnode(int op, NODE *left, NODE *right)
{
	register NODE *np;

	if ((np = malloc(sizeof (NODE))) == NULL)
		errx(1, nospace);
	np->n_op = op;
	np->n_left = left;
	np->n_right = right;
	np->n_un.n_val = 0;
    np->n_chars = 0;
    np->n_type = 0;
	return (np);
}

/*
 * Build a leaf node in expression tree.
 */
NODE *lnode(int op, int (*fn)(NODE *), unsigned long val, char *str)
{
	register NODE *np;

	if ((np = malloc(sizeof (NODE))) == NULL)
		errx(1, nospace);
	np->n_left = np->n_right = NULL;
	np->n_op = op;
    np->n_chars = 0;
    np->n_type = 0;
	np->n_fun = fn;
	if (str != NULL)
		np->n_un.n_str = str;
	else
		np->n_un.n_val = val;
	return (np);
}

/*
 * Build an execution node
 * for -ok or -exec.
 */
NODE *enode(int type)
{
	register NODE *np;
	register char **app;
	register char *ap;

	seflag++;
	np = snode(xexec, NULL);
	np->n_type = type;
	if ((np->n_un.n_strp = (char**)malloc(sizeof(char*[NARG])))==NULL)
		errx(1, nospace);
	app = np->n_un.n_strp;
	for (;;) {
		if ((ap = next()) == NULL)
			errx(1, "Non-terminated -exec or -ok command list");
		if (strcmp(ap, "{}") == 0)
			ap = FILEARG;
		else if (strcmp(ap, ";") == 0)
			break;
		if (app-np->n_un.n_strp >= NARG-1)
			errx(1, "Too many -exec or -ok command arguments");
		*app++ = ap;
	}
	*app = NULL;
	return (np);
}

/*
 * Execute find on a single
 * pathname hierarchy.
 */

/* Ripple: close each directory before descending, so depth consumes stack
 * and pathname space rather than descriptors or extra process slots. */
void find(char *dir)
{
    size_t n = strlen(dir);
    if (n >= sizeof(fname)) {
        warnx("%s: pathname too long", dir);
        failed = 1;
        return;
    }
    strcpy(fname, dir);
    while (n > 1 && fname[n-1] == '/')
        fname[--n] = 0;
    if (stat(fname, &sb) < 0) {
        warn("%s", fname);
        failed = 1;
        return;
    }
    fentry(fname+n, &sb);
}

void fentry(char *ep, struct stat *sbp)
{
    DIR *dir;
    struct dirent *dp;
    int isdir = S_ISDIR(sbp->st_mode);
    execute(code);
    if (!isdir)
        return;
    if (++depth > 128) {
        warnx("%s: %s", fname, toodeep);
        failed = 1;
        depth--;
        return;
    }
    dir = opendir(fname);
    if (!dir) {
        warn("%s", fname);
        failed = 1;
        depth--;
        return;
    }
    for (;;) {
        char *end;
        off_t position;
        errno = 0;
        dp = readdir(dir);
        if (!dp) {
            if (errno) {
                warn("%s", fname);
                failed = 1;
            }
            break;
        }
        if (!strcmp(dp->d_name,".") || !strcmp(dp->d_name,".."))
            continue;
        end = buildname(dp, ep);
        if (!end) {
            failed = 1;
            continue;
        }
        position = telldir(dir);
        closedir(dir);
        if (stat(fname, &sb) < 0) {
            warn("%s", fname);
            failed = 1;
        } else
            fentry(end, &sb);
        *ep = 0;
        dir = opendir(fname);
        if (!dir) {
            warn("%s", fname);
            failed = 1;
            break;
        }
        seekdir(dir, position);
    }
    *ep = 0;
    if (dir)
        closedir(dir);
    depth--;
}

/*
 * Build up the next entry
 * in the name.
 */
char *buildname(struct dirent *dp, char *ep)
{
	register char *cp = dp->d_name;
	register unsigned n = DIRSIZ;

	if (ep+DIRSIZ+2 > &fname[NFNAME-1]) {
		warn(toodeep);
		return (NULL);
	}
	if (ep>fname && ep[-1]!='/')
		*ep++ = '/';
	do {
		if (*cp == '\0')
			break;
		*ep++ = *cp++;
	} while (--n);
	*ep = '\0';
	return (ep);
}

/*
 * Execute compiled code.
 */
int execute(NODE *np)
{
	switch (np->n_op) {
	case AND:
		if (execute(np->n_left) && execute(np->n_right))
			return (1);
		return (0);

	case OR:
		if (execute(np->n_left) || execute(np->n_right))
			return (1);
		return (0);

	case '!':
		return (!execute(np->n_left));

	case FUN:
		return ((*np->n_fun)(np));

	default:
		errx(1, "Panic: bad expression tree (op %d)", np->n_op);
	}
	return 0; /* NOTREACHED */
}

/* 
 * pnmatch(string, pattern, unanchored)
 * returns 1 if pattern matches in string.
 * pattern:
 *	[c1c2...cn-cm]	class of characters.
 *	?		any character.
 *	*		any # of any character.
 *	^		beginning of string (if unanchored)
 *	$		end of string (if unanchored)
 * unanch:
 *	0		normal (anchored) pattern.
 *	1		unanchored (^$ also metacharacters)
 *	>1		end unanchored.
 * >1 is used internally but should not be used by the user.
 */

int pnmatch(const char *s, const char *p, int unanch)
{
	int c1;
	int c2;

	if (unanch == 1) {
		while (*s)
			if (pnmatch(s++, p, ++unanch))
				return (1);
		return (0);
	}
	while (c2 = *p++) {
		c1 = *s++;
		switch(c2) {
		case '^':
			if (unanch == 2) {
				s--;
				continue;
			} else if (unanch == 0)
				break;
			else
				return (0);

		case '$':
			if (unanch)
				return (c1 == '\0');
			break;

		case '[':
			for (;;) {
				c2 = *p++;
				if (c2=='\0' || c2==']')
					return (0);
				if (c2 == '\\' && *p == '-') 
					c2 = *p++;
				if (c2 == c1)
					break;
				if (*p == '-')
					if (c1<=*++p && c1>=c2)
						break;
			}
			while (*p && *p++!=']')
				;

		case '?':
			if (c1)
				continue;
			return(0);

		case '*':
			if (!*p)
				return(1);
			s--;
			do {
				if (pnmatch(s, p, unanch))
					return (1);
			} while(*s++ != '\0');
			return(0);

		case '\\':
			if ((c2 = *p++) == '\0')
				return (0);
		}
		if (c1 != c2)
			return (0);
	}
	return(unanch ? 1 : !*s);
}

/*
 * Check for a match on the filename
 */
int xname(NODE *np)
{
	register char *ep;

	ep = fname;
	while (*ep != '\0')
		ep++;
	while (ep>fname && *--ep!='/')
		;
	if (*ep == '/')
		ep++;
	return (pnmatch(ep, np->n_un.n_str, 0));
}

/*
 * Compare the mode for a match again
 * octal number `np->n_un.n_val'.
 */
int xperm(NODE *np)
{
	register int onum;
	register int mode;

	mode = np->n_type<0 ? sb.st_mode&017777 : sb.st_mode&07777;
	onum = np->n_un.n_val;
	if (np->n_type < 0)
		return ((mode&onum) == onum);
	return (mode == onum);
}

/*
 * Compare again filetypes
 */
int xtype(NODE *np)
{
	register char *type;
	register int ftype;

	type = np->n_un.n_str;
	ftype = sb.st_mode&S_IFMT;
	if (type[1] == '\0')
		switch (type[0]) {
		case 'b':
			return (ftype == S_IFBLK);
	
		case 'c':
			return (ftype == S_IFCHR);
	
		case 'd':
			return (ftype == S_IFDIR);
	
		case 'f':
			return (ftype == S_IFREG);

#ifdef S_IFMPB	
		case 'm':
			return (ftype==S_IFMPB || ftype==S_IFMPC);
#endif			
		case 'p':
			return (ftype == S_IFIFO);
		}
	errx(1, "Bad file type `%s'", type);
    return 0;
}

/*
 * Numerical compare.
 */
int ncomp(NODE *np, unsigned long val)
{
	if (np->n_type == 0)
		return (np->n_un.n_val == val);
	if (np->n_type > 0)
		return (val > np->n_un.n_val);
	return (val < np->n_un.n_val);
}
/*
 * Compare link counts.
 */
int xlinks(NODE *np)
{
	return (ncomp(np, sb.st_nlink));
}

/*
 * Compare uid.
 */
int xuser(NODE *np)
{
	return (np->n_un.n_val == sb.st_uid);
}

/*
 * Compare group id of file
 * with given one.
 */
int xgroup(NODE *np)
{
	return (np->n_un.n_val == sb.st_gid);
}

/*
 * Compare size of file in blocks
 * with given.
 */
int xsize(NODE *np)
{
    unsigned long size = sb.st_size;
    if (!np->n_chars)
        size = (size + 511) / 512;
    return ncomp(np, size);
}

/*
 * Compare the i-number of the file
 * with that given.
 */
int xinum(NODE *np)
{
	return (ncomp(np, sb.st_ino));
}

/*
 * Do a numerical comparison on dates.
 */
int ndays(NODE *np, time_t t)
{
    long delta=(long)curtime-(long)t;
    /* Future timestamps have negative ages, not wrapped unsigned ages. */
    if (delta<0)
        return np->n_type<0;
    return ncomp(np,delta/DAYSEC);
}


/*
 * Return true if file has been accessed
 * in `n' days.
 */
int xatime(NODE *np)
{
	return (ndays(np, sb.st_atime));
}

/*
 * Return non-zero if file has been created
 * in `n' days.
 */
int xctime(NODE *np)
{
	return (ndays(np, sb.st_ctime));
}

/*
 * Return true if file has been modified
 * in `n' days.
 */
int xmtime(NODE *np)
{
	return (ndays(np, sb.st_mtime));
}

/*
 * Execute a command based on the filename
 */
/* Pass arguments directly: spaces/metacharacters in a pathname are data. */
int xexec(NODE *np)
{
    char *args[NARG];
    char **src = np->n_un.n_strp;
    int n = 0, pid, status, result;
    while (*src) {
        args[n++] = *src == FILEARG ? fname : *src;
        src++;
    }
    args[n] = NULL;
    if (!n)
        errx(1, "empty -exec command");
    if (np->n_type) {
        int c;
        for (n = 0; args[n]; n++)
            printf("%s ", args[n]);
        printf("? ");
        fflush(stdout);
        c = getchar();
        result = c == 'y';
        while (c != '\n' && c != EOF)
            c = getchar();
        if (!result)
            return 0;
    }
    fflush(NULL);
    pid = fork();
    if (pid < 0) {
        warn("fork");
        failed = 1;
        return 0;
    }
    if (!pid) {
        execvp(args[0], args);
        warn("%s", args[0]);
        _exit(127);
    }
    do {
        result = waitpid(pid, &status, 0);
    } while (result < 0 && errno == EINTR);
    if (result < 0) {
        warn("waitpid");
        failed = 1;
        return 0;
    }
    return WIFEXITED(status) && WEXITSTATUS(status) == 0;
}

/*
 * Print the filename.
 */
/* ARGSUSED */
int xprint(NODE *np)
{
	printf("%s\n", fname);
	return (1);
}

int xnop(NODE *np)
{
	return (1);
}

/*
 * Return true if the file is newer than
 * the given one.
 */
int xnewer(NODE *np)
{
	return (sb.st_mtime > np->n_un.n_time);
}

void usage(void)
{
	fprintf(stderr, "Usage: find path ... [ expression ]\n");
    exit(1);
}
